UPDATE LocalizedText SET Text='[B]+4[icon:YIELD_CULTURE][/B]。此[icon:YIELD_CITIES]城市中的[icon:CITY_BUILDING_LIST][TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]防御工事建筑[/TIP]、[icon:CITY_RURAL][TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]改良设施[/TIP]和[icon:WONDER]奇观[B]+1[icon:YIELD_CULTURE][/B]和[icon:YIELD_GOLD]。[TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]无时代限制[/TIP]。己方所有[icon:Action_Fortify]防御工事[B]+1[icon:CULTURE_VP][/B][TIP:LOC_PEDIA_CONCEPTS_TOURISTS_TOOLTIP]观光值[/TIP]。必须放置在[icon:CITY_URBAN][TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]区块[/TIP]旁。' WHERE Language='zh_Hans_CN' AND Tag='LOC_WONDER_FORBIDDEN_CITY_DESCRIPTION' AND Text='[B]+4[icon:YIELD_CULTURE][/B]。所有[icon:CITY_BUILDING_LIST][TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]防御工事建筑[/TIP]、[icon:CITY_RURAL][TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]改良设施[/TIP]和[icon:WONDER]奇观[B]+1[icon:YIELD_CULTURE][/B]和[icon:YIELD_GOLD]。[TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]无时代限制[/TIP]。此[icon:YIELD_CITIES]城市中的[icon:Action_Fortify]防御工事[B]+1[icon:CULTURE_VP][/B][TIP:LOC_PEDIA_CONCEPTS_TOURISTS_TOOLTIP]观光值[/TIP]。必须放置在[icon:CITY_URBAN][TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]区块[/TIP]旁。';
UPDATE LocalizedText SET Text='此[icon:YIELD_CITIES]城市中的[icon:CITY_BUILDING_LIST][TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]防御工事建筑[/TIP]、[icon:CITY_RURAL][TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]改良设施[/TIP]和[icon:WONDER]奇观[B]+1[icon:YIELD_CULTURE][/B]和[icon:YIELD_GOLD]。[N]己方所有[icon:Action_Fortify]防御工事[B]+1[icon:CULTURE_VP][/B][TIP:LOC_PEDIA_CONCEPTS_TOURISTS_TOOLTIP]观光值[/TIP]。[N]必须放置在[icon:CITY_URBAN][TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]区块[/TIP]旁。' WHERE Language='zh_Hans_CN' AND Tag='LOC_WONDER_FORBIDDEN_CITY_TOOLTIP' AND Text='所有[icon:CITY_BUILDING_LIST][TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]防御工事建筑[/TIP]、[icon:CITY_RURAL][TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]改良设施[/TIP]和[icon:WONDER]奇观[B]+1[icon:YIELD_CULTURE][/B]和[icon:YIELD_GOLD]。[N]此[TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]定居点[/TIP]中的[icon:Action_Fortify]防御工事[B]+1[icon:CULTURE_VP][/B][TIP:LOC_PEDIA_CONCEPTS_TOURISTS_TOOLTIP]观光值[/TIP]。[N]必须放置在[icon:CITY_URBAN][TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]区块[/TIP]旁。';
UPDATE LocalizedText SET Text='[TIP:LOC_PEDIA_CONCEPTS_ISLAND_TOOLTIP]岛屿[/TIP]上的宫殿和市政厅+3[icon:YIELD_CULTURE]、[icon:YIELD_HAPPINESS]和[icon:YIELD_PRODUCTION]。无时代限制。必须放置在与陆地相邻的水岸上，且此定居点必须位于岛屿上。' WHERE Language='zh_Hans_CN' AND Tag='LOC_WONDER_NAN_MADOL_DESCRIPTION' AND Text='[TIP:LOC_PEDIA_CONCEPTS_ISLAND_TOOLTIP]岛屿[/TIP]上的宫殿和市政厅+3[icon:YIELD_CULTURE]、[icon:YIELD_HAPPINESS]和[icon:YIELD_PRODUCTION]。无时代限制。必须放置在与陆地相邻的水岸上，且此陆地必须为岛屿。';
